export default function DogThisYear() {
const { months } = useWidgetData();
const { locale, currency, privacyMode } = useWidgetEnv();
const thisMonth = new Date().toISOString().slice(0, 7);
const monthName = new Intl.DateTimeFormat(locale, { month: 'narrow', timeZone: 'UTC' });
const elapsed = months.data.buckets.filter((bucket) => bucket.month <= thisMonth);
const rows = elapsed.map((bucket) => ({
    month: monthName.format(new Date(`${bucket.month}-01T00:00:00Z`)),
    spent: Math.abs(bucket.sum),
}));
const total = rows.reduce((sum, row) => sum + row.spent, 0);
const payments = elapsed.reduce((sum, bucket) => sum + bucket.count, 0);

if (payments === 0) {
    return <EmptyState title="Gastado en el perro" description="Desde el 1 de enero" />;
}

return (
    <div className="flex h-full flex-col gap-3 p-5">
        <div className="flex items-center gap-2">
            <PawPrint size={16} className="text-amber-600 dark:text-amber-400" />
            <h3 className="text-sm font-medium">Gastado en el perro</h3>
        </div>
        <div className="flex flex-col gap-1">
            <Amount amount={total} currency={currency} className="text-4xl font-semibold tracking-tight" />
            <p className="text-xs text-muted-foreground">
                Desde el 1 de enero · {payments} pagos
            </p>
        </div>
        <div className="min-h-0 flex-1">
            <ResponsiveContainer width="100%" height="100%">
                <BarChart data={rows}>
                    <XAxis dataKey="month" tickLine={false} axisLine={false} />
                    <ChartTooltip valueFormatter={(value) => (privacyMode ? '•••' : formatMoney(value, currency))} />

